/**
 * The claim result the office settles when this incident is reported against a
 * freshly quoted policy covering these items -- the quote-then-claim envelope
 * every claim example in the specification describes.
 */
function claimSettledOn(
  insuredItems: Item[],
  incident: Incident,
): { payout: number; remainingCap: number } {
  const { results } = runScenario({
    customer: { yearsWithMHPCO: 0 },
    steps: [
      { op: "quote", items: insuredItems },
      { op: "claim", policy: 0, incident },
    ],
  });
  return results[1] as { payout: number; remainingCap: number };
}

describe("MHPCO Claim Office", () => {
  it("quote with an unknown item type (broomstick) -> throws an Error", () => {
    expect(() => premiumQuotedFor([{ type: "broomstick" }])).toThrow(Error);
  });

  // --- Claim: insurance sum and cap ---
  it.todo("policy covering a sword -> insurance sum 1000 G, cap 2000 G");
  it("policy covering a sword and an amulet -> insurance sum 1600 G, cap 3200 G", () => {
    expect(
      claimSettledOn(
        [
          { type: "sword", material: "steel", enchantment: 3, cursed: false },
          { type: "amulet", material: "silver", enchantment: 2, cursed: false },
        ],
        { cause: "fire", damages: [{ itemType: "sword", amount: 100 }] },
      ),
    ).toEqual({ payout: 0, remainingCap: 3200 });
  });
  it.todo("policy covering two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes (a block) -> insurance sum 1750 G; the block discount does not change the insurance sum");
  it.todo("cursed sword (premium with modifiers 165 G) -> cap 2000 G, based on the unmodified insurance value");

  // --- Claim: precedence where both special clauses cover one item ---
  // The dragon clause would pay the damage in full; the high-enchantment clause
  // pays half. The specification settles the conflict in the MHPCO's favour --
  // "the 50 % rule wins" -- so above the enchantment line the payout is the same
  // 400 G whether the sword is dragon or steel, and the dragon material buys the
  // claimant nothing. Read against the enchantment-5 case above, which is the
  // same dragon sword below the line and does pay in full.
  it("dragon-material sword enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins over dragon material)", () => {
    expect(
      claimSettledOn([{ type: "sword", material: "dragon", enchantment: 9, cursed: false }], {
        cause: "dragon attack",
        damages: [{ itemType: "sword", amount: 1000 }],
      }),
    ).toEqual({ payout: 400, remainingCap: 1600 });
  });
  it("dragon-material sword enchantment 8, damage 1000 G -> payout 400 G (high-enchantment clause applies, then deductible)", () => {
    expect(
      claimSettledOn([{ type: "sword", material: "dragon", enchantment: 8, cursed: false }], {
        cause: "dragon attack",
        damages: [{ itemType: "sword", amount: 1000 }],
      }),
    ).toEqual({ payout: 400, remainingCap: 1600 });
  });

  // --- Claim: deductible per damage event ---
  it("dragon attack damaging a sword (500 G) and an amulet (300 G) -> payout 600 G (deductible applies once per damaged item)", () => {
    expect(
      claimSettledOn(
        [
          { type: "sword", material: "steel", enchantment: 3, cursed: false },
          { type: "amulet", material: "silver", enchantment: 2, cursed: false },
        ],
        {
          cause: "dragon attack",
          damages: [
            { itemType: "sword", amount: 500 },
            { itemType: "amulet", amount: 300 },
          ],
        },
      ),
    ).toEqual({ payout: 600, remainingCap: 2600 });
  });
  it.todo("two sword damages against a policy covering two swords -> each entry is a separate damage with its own deductible");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("sword policy (cap 2000 G), first claim of 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second successive claim of 1500 G -> payout 600 G, remainingCap 0 G (reduced to the remaining cap)");

  // --- Claim: rounding in MHPCO's favour ---
  it.todo("a payout calculation yielding 350.5 G -> final payout 350 G (rounded down)");

  // --- Claim: rejections ---
  it.todo("claim naming an item type not covered by the policy (amulet when only a sword is insured) -> throws an Error; CLI exits non-zero with a stderr description");
  it.todo("claim naming an unknown item type -> throws an Error; CLI exits non-zero with a stderr description");
  it.todo("claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -> throws an Error; CLI exits non-zero with a stderr description");
  it.todo("claim with a damage entry of amount -200 -> throws an Error; CLI exits non-zero with a stderr description");

  // --- CLI adapter ---
  it.todo("CLI reads the schema example scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI emits one result per step: {premium} for quote steps, {payout, remainingCap} for claim steps");
  it.todo("CLI exits with status 0 and writes valid JSON for a successful scenario");
});

